 local actorGuid=UnitGUID("player");local actorAccount=HolyStorm.TwinkCore and HolyStorm.TwinkCore:GetAccountUUIDForCharacter(actorGuid);candidate.authorGuid=current and current.authorGuid or candidate.authorGuid or actorGuid;candidate.authorAccountUUID=current and current.authorAccountUUID or candidate.authorAccountUUID or actorAccount;candidate.author=current and current.author or candidate.author or GetUnitName("player",true);candidate.createdAt=current and current.createdAt or candidate.createdAt or now();candidate.createdBy=current and current.createdBy or candidate.createdBy or actorGuid;candidate.modifiedAt=now();candidate.modifiedBy=actorGuid;candidate.revision=(current and current.revision or 0)+1
