function Content:SaveDraft(entry,expectedRevision)entry=copy(entry);entry.status="DRAFT";return self:Save(entry,expectedRevision)end
function Content:Publish(entry,expectedRevision)entry=copy(entry);entry.status="PUBLISHED";return self:Save(entry,expectedRevision)end
