function Content:Delete(id,expectedRevision)local entry=self:Get(id);if not entry then return false,"NOT_FOUND"end;if not (HolyStorm.PermissionEngine or HolyStorm.Policy):Can(permission(entry,"delete"),nil,nil,entry)then return false,"PERMISSION_DENIED"end;if tonumber(expectedRevision)~=tonumber(entry.revision)then return false,"CONFLICT",entry.revision end;entry=copy(entry);entry.status="DELETED";entry.deletedAt=now();entry.deletedBy=UnitGUID("player");return self:Save(entry,expectedRevision)
